Async worker pipeline: test without waiting for real delays. Save /workspace/worker.py:

import asyncio

async def process_batch(items, handler, max_retries=2, backoff_s=1.0):
    results = {}
    for item in items:
        attempt = 0
        while True:
            try:
                results[item] = await handler(item)
                break
            except Exception as e:
                attempt += 1
                if attempt > max_retries:
                    results[item] = f"failed: {e}"
                    break
                await asyncio.sleep(backoff_s * (2 ** (attempt - 1)))
    return results

